{"path":"test/pagination.test.js","content":"'use strict'

const { test } = require('node:test')
const assert = require('node:assert')
const { paginate } = require('../src/pagination')

const items = [1, 2, 3, 4, 5]

test('page 1 is the first limit items and page 2 the next ones', () => {
  assert.deepStrictEqual(paginate(items, { page: 1, limit: 2 }).items, [1, 2])
  assert.deepStrictEqual(paginate(items, { page: 2, limit: 2 }).items, [3, 4])
  assert.strictEqual(paginate(items, { page: 2, limit: 2 }).page, 2)
})

test('a missing, unreadable or too small page falls back to page 1', () => {
  for (const page of [undefined, '', 'abc', 0, -3, null]) {
    const result = paginate(items, { page, limit: 2 })
    assert.strictEqual(result.page, 1)
    assert.deepStrictEqual(result.items, [1, 2])
  }
})

test('a page past the end is empty', () => {
  const result = paginate(items, { page: 9, limit: 2 })
  assert.strictEqual(result.page, 9)
  assert.deepStrictEqual(result.items, [])
})
"}

